import{_ as e,c as a,o as t,a2 as s}from"./chunks/framework.DdOM6S6U.js";const k=JSON.parse('{"title":"FileLibraryController","description":"","frontmatter":{"sidebarPos":10,"sidebarTitle":"FileLibraryController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/file-library-controller.md","filePath":"system-reference/backend/http/controllers/file-library-controller.md","lastUpdated":1778363927000}'),o={name:"system-reference/backend/http/controllers/file-library-controller.md"},i=s('<h1 id="filelibrarycontroller" tabindex="-1">FileLibraryController <a class="header-anchor" href="#filelibrarycontroller" aria-label="Permalink to &quot;FileLibraryController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/FileLibraryController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers</code><br><strong>Extends</strong>: <code>BaseController</code><br><strong>Implements</strong>: <code>SignUploadListener</code></p><p>Manages the file library — uploading, listing, tagging, and (optionally) cloud-signing files. Supports local filesystem storage, Amazon S3, and Azure Blob Storage.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>$moduleName</code></td><td><code>string</code></td><td><code>&#39;File&#39;</code></td><td>—</td></tr><tr><td><code>$routeName</code></td><td><code>string</code></td><td><code>&#39;File&#39;</code></td><td>—</td></tr><tr><td><code>$routePrefix</code></td><td><code>string</code></td><td><code>&#39;file-library&#39;</code></td><td>—</td></tr><tr><td><code>$perPage</code></td><td><code>int</code></td><td><code>40</code></td><td>Files per page</td></tr><tr><td><code>$endpointType</code></td><td><code>string</code></td><td>—</td><td><code>&#39;local&#39;</code> or cloud provider key</td></tr><tr><td><code>$defaultFilters</code></td><td><code>array</code></td><td><code>[&#39;search&#39;, &#39;tag&#39;, &#39;unused&#39;]</code></td><td>Active filter keys</td></tr><tr><td><code>$defaultOrders</code></td><td><code>array</code></td><td><code>[[&#39;column&#39; =&gt; &#39;id&#39;, &#39;direction&#39; =&gt; &#39;desc&#39;]]</code></td><td>Default sort</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="index-parentid-null-array" tabindex="-1"><code>index($parentId = null): array</code> <a class="header-anchor" href="#index-parentid-null-array" aria-label="Permalink to &quot;`index($parentId = null): array`&quot;">​</a></h3><p>Returns a paginated list of files with filtering by search term, tag, and unused status.</p><h3 id="getindexdata-array-scopes-array" tabindex="-1"><code>getIndexData(array $scopes): array</code> <a class="header-anchor" href="#getindexdata-array-scopes-array" aria-label="Permalink to &quot;`getIndexData(array $scopes): array`&quot;">​</a></h3><p>Returns <code>[&#39;files&#39;, &#39;maxPage&#39;, &#39;total&#39;, &#39;tags&#39;]</code> — the raw data used by the index view.</p><h3 id="store-parentid-null-jsonresponse" tabindex="-1"><code>store($parentId = null): JsonResponse</code> <a class="header-anchor" href="#store-parentid-null-jsonresponse" aria-label="Permalink to &quot;`store($parentId = null): JsonResponse`&quot;">​</a></h3><p>Dispatches to <code>storeFile()</code> for local uploads or <code>storeReference()</code> for cloud references.</p><h3 id="storefile-request-request-file" tabindex="-1"><code>storeFile(Request $request): File</code> <a class="header-anchor" href="#storefile-request-request-file" aria-label="Permalink to &quot;`storeFile(Request $request): File`&quot;">​</a></h3><p>Handles a local file upload:</p><ol><li>Sanitises the filename (whitespace → dashes).</li><li>Generates a UUID-based storage path with an optional local prefix.</li><li>Stores via the configured disk.</li><li>Persists the <code>File</code> record.</li></ol><h3 id="storereference-request-request-file" tabindex="-1"><code>storeReference(Request $request): File</code> <a class="header-anchor" href="#storereference-request-request-file" aria-label="Permalink to &quot;`storeReference(Request $request): File`&quot;">​</a></h3><p>Records a reference to a file already stored in cloud storage (bypasses local upload).</p><h3 id="singleupdate-jsonresponse" tabindex="-1"><code>singleUpdate(): JsonResponse</code> <a class="header-anchor" href="#singleupdate-jsonresponse" aria-label="Permalink to &quot;`singleUpdate(): JsonResponse`&quot;">​</a></h3><p>Updates tags for a single file.</p><h3 id="bulkupdate-jsonresponse" tabindex="-1"><code>bulkUpdate(): JsonResponse</code> <a class="header-anchor" href="#bulkupdate-jsonresponse" aria-label="Permalink to &quot;`bulkUpdate(): JsonResponse`&quot;">​</a></h3><p>Updates tags for multiple files in one request.</p><h3 id="signs3upload-request-request-signs3upload-signer-mixed" tabindex="-1"><code>signS3Upload(Request $request, SignS3Upload $signer): mixed</code> <a class="header-anchor" href="#signs3upload-request-request-signs3upload-signer-mixed" aria-label="Permalink to &quot;`signS3Upload(Request $request, SignS3Upload $signer): mixed`&quot;">​</a></h3><p>Signs an S3 pre-signed policy for direct browser-to-S3 uploads. Delegates to the <code>SignS3Upload</code> action class.</p><h3 id="signazureupload-request-request-signazureupload-signer-mixed" tabindex="-1"><code>signAzureUpload(Request $request, SignAzureUpload $signer): mixed</code> <a class="header-anchor" href="#signazureupload-request-request-signazureupload-signer-mixed" aria-label="Permalink to &quot;`signAzureUpload(Request $request, SignAzureUpload $signer): mixed`&quot;">​</a></h3><p>Returns an Azure Blob Storage SAS URL for direct browser-to-Azure uploads.</p><h3 id="uploadissigned-signature-bool-ispublic-false-jsonresponse-response" tabindex="-1"><code>uploadIsSigned($signature, bool $isPublic = false): JsonResponse|Response</code> <a class="header-anchor" href="#uploadissigned-signature-bool-ispublic-false-jsonresponse-response" aria-label="Permalink to &quot;`uploadIsSigned($signature, bool $isPublic = false): JsonResponse|Response`&quot;">​</a></h3><p>Called by <code>SignUploadListener</code> after a successful signing — returns the signed URL to the frontend.</p><h3 id="uploadisnotvalid-jsonresponse" tabindex="-1"><code>uploadIsNotValid(): JsonResponse</code> <a class="header-anchor" href="#uploadisnotvalid-jsonresponse" aria-label="Permalink to &quot;`uploadIsNotValid(): JsonResponse`&quot;">​</a></h3><p>Called by <code>SignUploadListener</code> on signing failure.</p><h3 id="shouldreplacefile-id-bool" tabindex="-1"><code>shouldReplaceFile($id): bool</code> <a class="header-anchor" href="#shouldreplacefile-id-bool" aria-label="Permalink to &quot;`shouldReplaceFile($id): bool`&quot;">​</a></h3><p>Returns <code>true</code> when a file with the given ID exists, indicating the upload is a replacement.</p><h3 id="buildfile-item-array" tabindex="-1"><code>buildFile($item): array</code> <a class="header-anchor" href="#buildfile-item-array" aria-label="Permalink to &quot;`buildFile($item): array`&quot;">​</a></h3><p>Formats a <code>File</code> model into the shape expected by the frontend:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;document.pdf&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mediableFormat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;--shiki-light-font-style:italic;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="getrequestfilters-array" tabindex="-1"><code>getRequestFilters(): array</code> <a class="header-anchor" href="#getrequestfilters-array" aria-label="Permalink to &quot;`getRequestFilters(): array`&quot;">​</a></h3><p>Extracts <code>search</code>, <code>tag</code>, and <code>unused</code> from the request.</p><h2 id="cloud-storage" tabindex="-1">Cloud Storage <a class="header-anchor" href="#cloud-storage" aria-label="Permalink to &quot;Cloud Storage&quot;">​</a></h2><p>Cloud signing is only triggered when <code>$endpointType</code> is not <code>&#39;local&#39;</code>. The controller implements <code>SignUploadListener</code> to handle the async result from the signing action classes.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./media-library-controller">MediaLibraryController</a> — image-specific variant with dimensions and alt text</li><li><a href="./filepond-controller">FilepondController</a> — temporary upload handler used before library storage</li></ul>',40),r=[i];function l(d,n,c,p,h,u){return t(),a("div",null,r)}const f=e(o,[["render",l]]);export{k as __pageData,f as default};
